mapper.select:
SELECT EXISTS (
    SELECT 1 FROM local_event_saves WHERE event_id = #{eventId} AND user_id = #{userId}
)

SELECT event_id FROM local_event_saves
WHERE user_id = #{userId} AND event_id IN
#{eventId}

SELECT s.user_id FROM local_event_saves s WHERE s.event_id = #{eventId} AND NOT EXISTS ( SELECT 1 FROM local_event_reminders r WHERE r.event_id = s.event_id AND r.user_id = s.user_id AND r.kind = #{kind})
AND NOT EXISTS ( SELECT 1 FROM user_checkins c WHERE c.local_event_id = s.event_id AND c.user_id = s.user_id AND c.is_removed = FALSE)
ORDER BY s.user_id LIMIT #{limit}
